#include <stdio.h>

int main() {
    int a[] = {1, 4, 7};
    int b[] = {2, 3, 9, 10};
    int merged[7];
    int i = 0, j = 0, k = 0;
    while (i < 3 && j < 4) {
        if (a[i] <= b[j]) merged[k++] = a[i++];
        else merged[k++] = b[j++];
    }
    while (i < 3) merged[k++] = a[i++];
    while (j < 4) merged[k++] = b[j++];
    for (int x = 0; x < k; x++) printf("%d ", merged[x]);
    printf("\n");
    return 0;
}
